// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 futureTimestamp, address sender) public {
        vm.assume(sender != address(0));
        futureTimestamp = bound(futureTimestamp, block.timestamp + 1, type(uint64).max);

        vm.deal(sender, 20 ether);

        vm.warp(futureTimestamp);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
